mapper.select:
SELECT br.id, br.user_id, u.nickname, br.change_type, br.change_amount, br.balance_after, br.trigger_scene, br.remark, br.create_time FROM balance_record br LEFT JOIN user_info u ON br.user_id = u.id AND u.del_flag = '0'
AND u.nickname LIKE CONCAT('%', #{nickname}, '%')
AND br.change_type = #{changeType}
AND br.create_time >= #{beginTime}
AND br.create_time <= #{endTime}
ORDER BY br.create_time DESC
